plugins.inlineStyle:
:root { color-scheme: only light; }
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: #ffffff; color: #111111; }
body { font-family: -apple-system, "PingFang SC", "Microsoft YaHei", "Noto Sans SC", sans-serif; font-size: 14px; line-height: 1.5; }
.panel { padding: 12px; background: #ffffff; }
.row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.k { color: #666666; font-size: 12px; }
.v { font-weight: 600; overflow-wrap: anywhere; text-align: right; }
.bar { height: 6px; margin: 4px 0 10px; background: #ececec; border: 1px solid #cfcfcf; }
.fill { height: 100%; width: 0; background: #111111; }
